#include <iostream>
using namespace std;

int main() {
    int N, M;
    cin >> N >> M;

    // 大きさの合計を求める
    int sum = 0;
    for (int i = 0; i < N; ++i) {
        int A;
        cin >> A;
        sum += A;
    }

    // 大きさの合計が M 以下なら Yes
    if (sum <= M) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
    return 0;
}

N, M = map(int, input().split())

if sum(map(int, input().split())) <= M:
    print('Yes')
else:
    print('No')
